using System;

namespace Sensus.Captions;

// 40 ms RMS envelope of the original JackInTheBoxTheme (44100 Hz, 1890304 frames).
// A visual loudness trace, not an AI countdown or predicted pop time.
// Generated by scripts/generate_winding_envelope.py; no audio decoding in the HUD.
internal static class WindingEnvelope
{
    private static readonly byte[] Levels = Convert.FromBase64String("");
    internal static float At(float seconds)
    {
        if(float.IsNaN(seconds) || seconds<0 || seconds>=42.864036f) return 0;
        float sample=seconds*25;
        int index=(int)sample;
        if(index>=Levels.Length) return 0;
        float a=Levels[index]/255f;
        float b=Levels[Math.Min(index+1,Levels.Length-1)]/255f;
        return a+(b-a)*(sample-index);
    }
    internal static float Urgency(float seconds) => float.IsNaN(seconds) ? 0 : Math.Max(0,Math.Min(1,seconds/42.864036f));
    internal static float Shake(float seconds,bool live,bool lowMotion) =>
        lowMotion || !live || seconds<0 ? 0 : (2+12*Urgency(seconds))*(float)Math.Sin(2*Math.PI*(2*seconds+0.08f*seconds*seconds));
    internal static float Scale(float envelope,bool live,bool lowMotion) =>
        lowMotion || !live ? 1 : 1+0.14f*Math.Max(0,Math.Min(1,envelope));
}
